WITH flattened_attrs AS (SELECT id, service, host, log_ts, level, latency_ms, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, COALESCE(context['version'], 'none') AS version_or_default FROM app_logs WHERE service <> 'billing') SELECT id, service, log_ts, latency_ms, duration_sec, version_or_default, DENSE_RANK() OVER (ORDER BY duration_sec) AS duration_sec_dense_rank, COUNT(latency_ms) OVER (PARTITION BY MONTH(log_ts), host) AS log_ts_month_count_latency_ms FROM flattened_attrs
